<template><view class="product-reviews"><text class="heading">买家评价（{{total}}）</text><text v-if="!rows.length&&!error" class="hint">暂无公开评价。</text><view v-for="r in rows" :key="r.id" class="entry"><view>{{r.nickname}} · {{r.stars}}星</view><text class="hint">已购 {{r.spec}}</text><view>{{r.body}}</view><image v-for="img in JSON.parse(r.images_json||'[]')" :key="img" :src="asset(img)" style="width:80px;height:80px" mode="aspectFill" @click="preview(r,img)"/><view v-if="r.followup">追评：{{r.followup}}</view><view v-if="r.reply" class="hint">商家回复：{{r.reply}}</view></view><button class="ui-button" v-if="rows.length<total||error" :disabled="busy" @click="load(false)">{{error?'重试加载':'查看更多评价'}}</button></view></template>
<script>
import {request,asset} from '../services/shop.js'
export default {props:{productId:{required:true}},data(){return{rows:[],total:0,page:1,busy:false,error:''}},watch:{productId:{immediate:true,handler(){this.rows=[];this.total=0;this.page=1;this.load(true)}}},methods:{asset,preview(r,img){uni.previewImage({current:asset(img),urls:JSON.parse(r.images_json||'[]').map(p=>asset(p))})},async load(reset){if(this.busy&&!reset)return;const id=this.productId,page=reset?1:this.page;this.busy=true;try{const r=await request('/products/'+id+'/reviews?page='+page);if(id!==this.productId)return;this.rows=reset?r.rows:[...this.rows,...r.rows];this.total=r.total;this.page=page+1;this.error=''}catch(e){this.error=e.message}finally{if(id===this.productId)this.busy=false}}}}
</script>
<style scoped>
@import '../styles/component-base.css';
.product-reviews{background:var(--shop-surface, #fdfeff);margin:16px;padding:16px;border-radius:12px;font-size:16px;line-height:1.8}.heading{font-size:20px;font-weight:bold;display:block}.hint{color:var(--shop-ink, #28546c);font-size:14px}.entry{padding:12px 0;border-bottom:1px solid var(--shop-border, #d5e6ee);overflow-wrap:anywhere}button{font-size:16px}</style>
